import json
import re
from collections import deque
from typing import Dict, List, Tuple

HEADER_RE = re.compile(r"^\[(.+?)\]\s*$")
CHOICE_RE = re.compile(r"^(\d+)\.\s*(.+?)\s*->\s*(\S+)\s*$")
LINE_RE = re.compile(r"^(.*?)\s*->\s*(\S+)\s*$")


def _parse_sections(text: str) -> Tuple[List[str], Dict[str, List[str]]]:
    order: List[str] = []
    sections: Dict[str, List[str]] = {}
    current = None
    for raw in text.splitlines():
        line = raw.rstrip("\n")
        m = HEADER_RE.match(line.strip())
        if m:
            current = m.group(1).strip()
            if current not in sections:
                order.append(current)
                sections[current] = []
            continue
        if current is None:
            # Skip stray lines before first header.
            continue
        sections[current].append(line)
    return order, sections


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    order, sections = _parse_sections(text)
    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []
    node_ids = set()

    for node_id in order:
        lines = [ln.strip() for ln in sections[node_id] if ln.strip()]
        if not lines:
            node = {"id": node_id, "text": "", "speaker": "", "type": "line"}
            nodes.append(node)
            node_ids.add(node_id)
            continue

        # Choice block if first non-empty line starts with a number.
        if CHOICE_RE.match(lines[0]):
            node = {"id": node_id, "text": "", "speaker": "", "type": "choice"}
            nodes.append(node)
            node_ids.add(node_id)
            for line in lines:
                m = CHOICE_RE.match(line)
                if not m:
                    continue
                choice_text = m.group(2).strip()
                target = m.group(3).strip()
                edges.append({"from": node_id, "to": target, "text": choice_text})
        else:
            # Line node. Use first non-empty line.
            m = LINE_RE.match(lines[0])
            target = None
            content = lines[0]
            if m:
                content = m.group(1).strip()
                target = m.group(2).strip()
            speaker = ""
            text_only = content
            if ":" in content:
                speaker, text_only = content.split(":", 1)
                speaker = speaker.strip()
                text_only = text_only.strip()
            node = {"id": node_id, "text": text_only, "speaker": speaker, "type": "line"}
            nodes.append(node)
            node_ids.add(node_id)
            if target:
                edges.append({"from": node_id, "to": target, "text": ""})

    # Add implicit nodes for any missing edge targets (e.g., End).
    targets = {e["to"] for e in edges if e.get("to")}
    for target in sorted(targets - node_ids):
        nodes.append({"id": target, "text": "", "speaker": "", "type": "line"})
        node_ids.add(target)

    graph = {"nodes": nodes, "edges": edges}
    _validate_graph(graph)
    return graph


def _validate_graph(graph: Dict[str, List[Dict[str, str]]]) -> None:
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])
    if not nodes:
        raise ValueError("Graph has no nodes.")

    ids = [n["id"] for n in nodes]
    if len(ids) != len(set(ids)):
        raise ValueError("Duplicate node ids detected.")
    id_set = set(ids)

    for e in edges:
        if e["from"] not in id_set:
            raise ValueError(f"Edge source missing: {e['from']}")
        if e["to"] not in id_set:
            raise ValueError(f"Edge target missing: {e['to']}")

    # Reachability from first node.
    start = nodes[0]["id"]
    adj = {nid: [] for nid in id_set}
    for e in edges:
        adj[e["from"]].append(e["to"])

    seen = set()
    q = deque([start])
    while q:
        cur = q.popleft()
        if cur in seen:
            continue
        seen.add(cur)
        for nxt in adj.get(cur, []):
            if nxt not in seen:
                q.append(nxt)

    unreachable = id_set - seen
    if unreachable:
        raise ValueError(f"Unreachable nodes: {sorted(unreachable)}")


def _escape_dot(s: str) -> str:
    return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n")


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines: List[str] = ["digraph Dialogue {", "  rankdir=LR;"]
    for node in graph["nodes"]:
        label = node["id"]
        if node["type"] == "choice":
            label = f"{label}\\n(choice)"
        else:
            if node["text"]:
                prefix = f"{node['speaker']}: " if node["speaker"] else ""
                label = f"{label}\\n{prefix}{node['text']}"
        lines.append(f"  \"{_escape_dot(node['id'])}\" [label=\"{_escape_dot(label)}\"];" )

    for edge in graph["edges"]:
        src = _escape_dot(edge["from"])
        dst = _escape_dot(edge["to"])
        if edge.get("text"):
            label = _escape_dot(edge["text"])
            lines.append(f"  \"{src}\" -> \"{dst}\" [label=\"{label}\"];" )
        else:
            lines.append(f"  \"{src}\" -> \"{dst}\";" )
    lines.append("}")
    return "\n".join(lines)


if __name__ == "__main__":
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()
    graph = parse_script(text)
    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2, ensure_ascii=True)
    dot = graph_to_dot(graph)
    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(dot)
